def f(n):
    if n == 0: return 0
    m = 0
    while n % 2 == 0:
        n //= 2
        m += 1
    return n

def check_v(v, u_max=2000):
    for u in range(1, u_max + 1):
        possible = True
        for k in range(v):
            if (f(u + v + k) - f(u + k)) % 4 != 0:
                possible = False
                break
        if possible:
            return True, u
    return False, None

results = []
for v in range(1, 21):
    found, u = check_v(v)
    results.append((v, found, u))

